  1430
  1431          // first we can export the "standard" properties
  1432          if (m->Get(AI_MATKEY_COLOR_AMBIENT, c) == aiReturn_SUCCESS) {
  1433              p.AddP70colorA("AmbientColor", c.r, c.g, c.b);
  1434              //p.AddP70numberA("AmbientFactor", 1.0);
  1435          }
  1436          if (m->Get(AI_MATKEY_COLOR_DIFFUSE, c) == aiReturn_SUCCESS) {
  1437              p.AddP70colorA("DiffuseColor", c.r, c.g, c.b);
  1438              //p.AddP70numberA("DiffuseFactor", 1.0);
  1439          }
  1440          if (m->Get(AI_MATKEY_COLOR_TRANSPARENT, c) == aiReturn_SUCCESS) {
  1441              // "TransparentColor" / "TransparencyFactor"...
  1442              // thanks FBX, for your insightful interpretation of consistency
  1443              p.AddP70colorA("TransparentColor", c.r, c.g, c.b);
  1444
  1445              if (!bTransparencyFactorReferencedToOpacity) {
  1446                  // TransparencyFactor defaults to 0.0, so set it to 1.0.
  1447                  // note: Maya always sets this to 1.0,
  1448                  // so we can't use it sensibly as "Opacity".
  1449                  // In stead we rely on the legacy "Opacity" value, below.
  1450                  // Blender also relies on "Opacity" not "TransparencyFactor",
  1451                  // probably for a similar reason.
  1452                  p.AddP70numberA("TransparencyFactor", 1.0);
  1453              }
  1454          }
  1455          if (bTransparencyFactorReferencedToOpacity) {
  1456              if (m->Get(AI_MATKEY_OPACITY, f) == aiReturn_SUCCESS) {
  1457                  p.AddP70numberA("TransparencyFactor", 1.0 - f);
  1458              }
  1459          }
  1460          if (m->Get(AI_MATKEY_COLOR_REFLECTIVE, c) == aiReturn_SUCCESS) {
  1461              p.AddP70colorA("ReflectionColor", c.r, c.g, c.b);
  1462          }
