  1468                  p.AddP70colorA("SpecularColor", c.r, c.g, c.b);
  1469              }
  1470              if (m->Get(AI_MATKEY_SHININESS_STRENGTH, f) == aiReturn_SUCCESS) {
  1471                  p.AddP70numberA("ShininessFactor", f);
  1472              }
  1473              if (m->Get(AI_MATKEY_SHININESS, f) == aiReturn_SUCCESS) {
  1474                  p.AddP70numberA("ShininessExponent", f);
  1475              }
  1476              if (m->Get(AI_MATKEY_REFLECTIVITY, f) == aiReturn_SUCCESS) {
  1477                  p.AddP70numberA("ReflectionFactor", f);
  1478              }
  1479          }
  1480
  1481          // Now the legacy system.
  1482          // For safety let's include it.
  1483          // thrse values don't exist in the property template,
  1484          // and usually are completely ignored when loading.
  1485          // One notable exception is the "Opacity" property,
  1486          // which Blender uses as (1.0 - alpha).
  1487          c.r = 0.0f; c.g = 0.0f; c.b = 0.0f;
  1488          m->Get(AI_MATKEY_COLOR_EMISSIVE, c);
  1489          p.AddP70vector("Emissive", c.r, c.g, c.b);
  1490          c.r = 0.2f; c.g = 0.2f; c.b = 0.2f;
  1491          m->Get(AI_MATKEY_COLOR_AMBIENT, c);
  1492          p.AddP70vector("Ambient", c.r, c.g, c.b);
  1493          c.r = 0.8f; c.g = 0.8f; c.b = 0.8f;
  1494          m->Get(AI_MATKEY_COLOR_DIFFUSE, c);
  1495          p.AddP70vector("Diffuse", c.r, c.g, c.b);
  1496          // The FBX SDK determines "Opacity" from transparency colour (RGB)
  1497          // and factor (F) as: O = (1.0 - F * ((R + G + B) / 3)).
  1498          // However we actually have an opacity value,
  1499          // so we should take it from AI_MATKEY_OPACITY if possible.
