  1513              m->Get(AI_MATKEY_SHININESS_STRENGTH, f);
  1514              p.AddP70vector("Specular", f*c.r, f*c.g, f*c.b);
  1515              f = 20.0f;
  1516              m->Get(AI_MATKEY_SHININESS, f);
  1517              p.AddP70double("Shininess", f);
  1518              // Legacy "Reflectivity" is F*F*((R+G+B)/3),
  1519              // where F is the proportion of light reflected (AKA reflectivity),
  1520              // and RGB is the reflective colour of the material.
  1521              // No idea why, but we might as well set it the same way.
  1522              f = 0.0f;
  1523              m->Get(AI_MATKEY_REFLECTIVITY, f);
  1524              c.r = 1.0f, c.g = 1.0f, c.b = 1.0f;
  1525              m->Get(AI_MATKEY_COLOR_REFLECTIVE, c);
  1526              p.AddP70double("Reflectivity", f*f*((c.r+c.g+c.b)/3.0));
  1527          }
